"""Publish this chat's M11 source candidates and bounded layout study."""
from pathlib import Path
from PIL import Image
import hashlib, html, json, re

OUT = Path(__file__).resolve().parent
def read(name): return json.loads((OUT/name).read_text())
def write(name, value): (OUT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def item(ident, file, source, prompt, role):
    with Image.open(OUT/file) as im:
        size=list(im.size); mode=im.mode
    return dict(id=ident,file=file,sha256=sha(OUT/file),pixel_size=size,mode=mode,generated_source=source,prompt_record=prompt,role=role,user_accepted=False,runtime_integrated=False,handoff_sent=False)

