esc=lambda x:html.escape(str(x),quote=True)
def fig(file,caption): return f'<figure><a href="{esc(file)}"><img src="{esc(file)}" alt="{esc(caption)}" loading="lazy"></a><figcaption>{esc(caption)}</figcaption></figure>'
css='''*{box-sizing:border-box}body{margin:0;background:#eef0ed;color:#172b3b;font-family:system-ui,-apple-system,sans-serif;line-height:1.7}main{max-width:1200px;margin:auto;padding:30px 22px 70px}nav,.links{display:flex;gap:18px;flex-wrap:wrap}a{color:#075b7b}h1{font-size:clamp(28px,4vw,44px);line-height:1.2;margin:20px 0}h2{margin-top:45px}p{max-width:950px}figure{margin:22px 0;background:#fff;border-radius:9px;overflow:hidden}img{display:block;width:100%;height:auto}figcaption{padding:10px 15px;font-size:14px;color:#405764}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.grid figure{margin:0}.note{border-left:4px solid #df8e28;padding:10px 16px;background:#fff7e8}.context{max-width:520px}.context img{max-height:700px;object-fit:contain}video{width:100%;max-height:700px;background:#333}table{width:100%;border-collapse:collapse;background:white}td,th{padding:12px;text-align:left;border-bottom:1px solid #d6dfdf}details{margin-top:30px;padding:18px;background:#e0e7e5}summary{cursor:pointer;font-weight:600}small{color:#516772}@media(max-width:680px){.grid{grid-template-columns:1fr}main{padding:22px 14px}table{font-size:13px}}'''
body='<nav><a href="index.html">返回素材总览</a><a href="#head">头部两案</a><a href="#vehicle">摄像头后视</a><a href="#layout">变形布局</a></nav><h1>货柜领袖：额框、侧盔与护颊连成整体</h1><p>按最新参考重新组织整个头盔。通讯结构融进两侧壳体，保留正常头高、藏蓝盔体、青色双眼与银色分节面甲。</p><h2 id="head">两种整体盔型</h2><p><b>A：厚实侧盔。</b>更沉稳的额框与护颊，侧面通讯窗贴合壳体。<br><b>B：连贯额框。</b>白色额框延伸至两侧，轮廓更流线，作者更倾向此方向。</p>'+fig(items[0]['file'],'A与B各有正面和左前斜视；当前头部两案，供比较')
body+='<p class="note">两案尚未合入整机。下面旧整机只展示颈下车壳和身体方向；其旧头部不代表本轮方案。</p><details><summary>查看颈下造型与用户参考</summary><div class="grid"><div class="context">'+fig(robot['file'],'此前未来人形母稿：仅颈下造型参考')+'</div>'+fig('samples/M11-user-helmet-reference-r4.png','用户提供的整体头盔构造参考，不照搬具体头脸')+'</div></details>'
body+='<h2 id="vehicle">后视改为明确的小型镜头窗口</h2><p>去掉容易看成反光镜的部位，用柱侧双镜头凹窗表达摄像头后视。流线车头、四轴和单个可卸货柜保持。</p>'+fig(items[1]['file'],'车形局部修正：柱侧摄像头后视及放大细节')
body+='<h2 id="layout">同一套零件的展开草模</h2><p>上一版只有外形部件对应，完整变形并未成立。本轮补了同一场景中的轮架、滑轨和铰链布局，货柜预先卸下留在地面；头部仅用通用包络，不代表上方A/B精确造型。</p><video controls preload="metadata" poster="M11-kinematic-r4/04-robot-head-up.png"><source src="M11-kinematic-r4/M11-layout-motion-r4.mp4" type="video/mp4">请打开<a href="M11-kinematic-r4/M11-layout-motion-r4.mp4">布局视频</a>。</video><p class="note">这是部件去向研究，尚未解决驾驶空间、全程碰撞净空、承重与展开支撑。作者已查看下面四个状态，视频导出成功不等于连续动作验收。</p><div class="grid">'
captions=['① 已卸柜车形：货柜完整保留','② 驾驶室后移、轮架与手臂打开','③ 后车架向下成腿、货台折叠','④ 本体展开：头部通用包络升起']
